SELECT symbol, id, generated_at, candle_open_time, decision, original_decision, total_score FROM crypto_ai.trade_signal WHERE interval_code = '5m' AND ((symbol = 'EGLDUSDT' AND generated_at BETWEEN '2026-10-11 20:35:00' AND '2026-10-11 20:55:02') OR (symbol = 'ACEUSDT' AND generated_at BETWEEN '2026-10-12 09:37:00' AND '2026-10-12 09:57:02')) ORDER BY symbol, generated_at LIMIT 20;